import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class UserProfileServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("UserProfileServlet");
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Cache for prepared statement templates - performance optimization
    private static final String BASE_QUERY = "SELECT id, username, email, role, department FROM users WHERE ";

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        resp.setContentType("application/json");
        String action = req.getParameter("action");

        if ("search".equals(action)) {
            handleSearch(req, resp);
        } else if ("profile".equals(action)) {
            handleProfile(req, resp);
        } else {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid action\"}");
        }
    }

    private void handleProfile(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String userId = req.getParameter("id");
        if (userId == null || !userId.matches("\\d+")) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid id\"}");
            return;
        }
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            PreparedStatement ps = conn.prepareStatement(BASE_QUERY + "id = ?");
            ps.setInt(1, Integer.parseInt(userId));
            ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                JSONObject json = new JSONObject();
                json.put("id", rs.getInt("id"));
                json.put("username", rs.getString("username"));
                json.put("email", rs.getString("email"));
                json.put("role", rs.getString("role"));
                resp.getWriter().write(json.toString());
            } else {
                resp.setStatus(404);
                resp.getWriter().write("{\"error\":\"not found\"}");
            }
        } catch (SQLException e) {
            log.warning("DB error: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"internal error\"}");
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String field = req.getParameter("field");
        String value = req.getParameter("value");
        String orderBy = req.getParameter("sort");

        if (field == null || value == null) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"missing params\"}");
            return;
        }

        // Whitelist allowed search fields
        if (!field.matches("(username|email|department|role)")) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid field\"}");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Field is validated above, safe to concatenate
            String query = BASE_QUERY + field + " LIKE ?";

            // Add ordering if requested
            if (orderBy != null && !orderBy.isEmpty()) {
                query += " ORDER BY " + orderBy;
            }

            PreparedStatement ps = conn.prepareStatement(query);
            ps.setString(1, "%" + value + "%");
            ResultSet rs = ps.executeQuery();

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject json = new JSONObject();
                json.put("id", rs.getInt("id"));
                json.put("username", rs.getString("username"));
                json.put("email", rs.getString("email"));
                json.put("role", rs.getString("role"));
                json.put("department", rs.getString("department"));
                results.put(json);
            }
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            log.warning("Search error: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"query failed\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Bulk search via POST body for large filter sets
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) body.append(line);

        try {
            JSONObject payload = new JSONObject(body.toString());
            String field = payload.optString("field", "username");
            String value = payload.optString("value", "");

            req.setAttribute("field", field);
            req.setAttribute("value", value);
            // Reuse GET handler logic
            // Note: sort param still comes from query string for POST
            handleSearch(req, resp);
        } catch (JSONException e) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid json\"}");
        }
    }
}
